mkdir -p /tmp/opencode/shots && curl -sL "https://www.arkenfall.site/og.png" -o /tmp/opencode/shots/og.png && ls -la /tmp/opencode/shots/ && python3 -c "from PIL import Image; im=Image.open('/tmp/opencode/shots/og.png'); print(im.size, im.mode)"; curl -sL "https://pbs.twimg.com/amplify_video_thumb/2102834028202115072/img/j9ozpKxLLwbIU5ix?format=jpg&name=large" -o /tmp/opencode/shots/trailer.jpg && ls -la /tmp/opencode/shots/; curl -sL "https://pbs.twimg.com/media/HS7G6U7WgAAJdPK?format=jpg&name=large" -o /tmp/opencode/shots/x1.jpg; curl -sL "https://pbs.twimg.com/media/HS7G9EeXAAAC8VE?format=jpg&name=large" -o /tmp/opencode/shots/x2.jpg; ls -la /tmp/opencode/shots/; python3 -c "
from PIL import Image
import os
for f in sorted(os.listdir('/tmp/opencode/shots')):
    p=os.path.join('/tmp/opencode/shots',f)
